```python
import pytest

from budget import BudgetExceeded, BudgetService, InMemoryUsageRepo


@pytest.mark.parametrize(
    ("already_used", "ask", "allowed"),
    [
        pytest.param(0, 1_000, True, id="exactly-at-limit"),
        pytest.param(999, 1, True, id="last-token"),
        pytest.param(1_000, 1, False, id="one-over"),
        pytest.param(0, 1_001, False, id="single-request-over"),
    ],
)
def test_limit_boundary(
    service: BudgetService, repo: InMemoryUsageRepo,
    already_used: int, ask: int, allowed: bool,
) -> None:
    if already_used:
        repo.add("acme", already_used)
    if allowed:
        assert service.charge("acme", ask) == already_used + ask
    else:
        with pytest.raises(BudgetExceeded):
            service.charge("acme", ask)


@pytest.mark.parametrize("bad", [0, -5], ids=["zero", "negative"])
def test_rejects_non_positive(service: BudgetService, bad: int) -> None:
    with pytest.raises(ValueError, match="positive"):
        service.charge("acme", bad)


def test_rejected_charge_has_no_side_effect(service: BudgetService) -> None:
    service.charge("acme", 900)
    with pytest.raises(BudgetExceeded) as excinfo:
        service.charge("acme", 200)
    assert excinfo.value.used == 900
    assert excinfo.value.requested == 200
    assert service.remaining("acme") == 100


def test_tenants_are_isolated(service: BudgetService) -> None:
    service.charge("acme", 800)
    assert service.charge("globex", 800) == 800
    assert service.remaining("acme") == 200
```

Run it with `pytest -q`.

`repo_factory` is parametrized, so every contract test is collected three times, and the `yield` section closes any SQLite connections that the factory opened. The SQL adapter commits per call so a second connection sees the data; the file adapter replaces the file atomically.

**`repos.py`**

```python
from __future__ import annotations

import json
import os
import sqlite3
from pathlib import Path


class SqlUsageRepo:
    """SQLite-backed repo; every add is committed so a second connection sees it."""

    def __init__(self, path: str | Path) -> None:
        self._conn = sqlite3.connect(path)
        self._conn.execute(
            "CREATE TABLE IF NOT EXISTS usage("
            "tenant TEXT PRIMARY KEY, tokens INTEGER NOT NULL)"
        )
        self._conn.commit()

    def get(self, tenant: str) -> int:
        row = self._conn.execute(
            "SELECT tokens FROM usage WHERE tenant = ?", (tenant,)
        ).fetchone()
        return int(row[0]) if row else 0

    def add(self, tenant: str, tokens: int) -> int:
        with self._conn:  # commits on success, rolls back on error
            self._conn.execute(
                "INSERT INTO usage(tenant, tokens) VALUES (?, ?) "
                "ON CONFLICT(tenant) DO UPDATE SET tokens = tokens + excluded.tokens",
                (tenant, tokens),
            )
        return self.get(tenant)

    def close(self) -> None:
        self._conn.close()


class FileUsageRepo:
    """JSON file repo with atomic replace so a crash never leaves a torn file."""

    def __init__(self, path: str | Path) -> None:
        self._path = Path(path)

    def _load(self) -> dict[str, int]:
        if not self._path.exists():
            return {}
        return json.loads(self._path.read_text(encoding="utf-8"))

    def get(self, tenant: str) -> int:
        return self._load().get(tenant, 0)

    def add(self, tenant: str, tokens: int) -> int:
        data = self._load()
        data[tenant] = data.get(tenant, 0) + tokens
        tmp = self._path.with_suffix(".tmp")
        tmp.write_text(json.dumps(data), encoding="utf-8")
        os.replace(tmp, self._path)
        return data[tenant]
```

**`test_contract.py`**

```python
from collections.abc import Callable, Iterator
from pathlib import Path

import pytest

from budget import BudgetExceeded, BudgetService, InMemoryUsageRepo, UsageRepo
from repos import FileUsageRepo, SqlUsageRepo

RepoFactory = Callable[[], UsageRepo]


@pytest.fixture(params=["memory", "sql", "file"])
def repo_factory(request: pytest.FixtureRequest, tmp_path: Path) -> Iterator[RepoFactory]:
    """Return a factory; every call yields a repo over the SAME storage."""
    opened: list[SqlUsageRepo] = []
    if request.param == "memory":
        shared = InMemoryUsageRepo()
        def factory() -> UsageRepo:
            return shared
    elif request.param == "sql":
        def factory() -> UsageRepo:
            r = SqlUsageRepo(tmp_path / "usage.db")
            opened.append(r)
            return r
    else:
        def factory() -> UsageRepo:
            return FileUsageRepo(tmp_path / "usage.json")
    yield factory
    for r in opened:
        r.close()


def test_unknown_tenant_is_zero(repo_factory: RepoFactory) -> None:
    assert repo_factory().get("nobody") == 0


def test_add_returns_running_total(repo_factory: RepoFactory) -> None:
    repo = repo_factory()
    assert repo.add("acme", 10) == 10
    assert repo.add("acme", 5) == 15


def test_tenants_are_isolated(repo_factory: RepoFactory) -> None:
    repo = repo_factory()
    repo.add("acme", 10)
    assert repo.get("globex") == 0


def test_writes_visible_through_a_second_instance(repo_factory: RepoFactory) -> None:
    repo_factory().add("acme", 7)
    assert repo_factory().get("acme") == 7


def test_service_enforces_limit_on_every_backend(repo_factory: RepoFactory) -> None:
    service = BudgetService(repo_factory(), limit=100)
    service.charge("acme", 60)
    with pytest.raises(BudgetExceeded):
        service.charge("acme", 41)
    assert service.remaining("acme") == 40
```

